    if (linear_init(&model->enc_gru2_recurrent, arrays, "enc_gru2_recurrent_bias", "enc_gru2_recurrent_subias", "enc_gru2_recurrent_weights_int8","enc_gru2_recurrent_weights_float", NULL, NULL, "enc_gru2_recurrent_scale", 32, 96)) return 1;
    if (linear_init(&model->enc_gru3_input, arrays, "enc_gru3_input_bias", "enc_gru3_input_subias", "enc_gru3_input_weights_int8","enc_gru3_input_weights_float", "enc_gru3_input_weights_idx", NULL, "enc_gru3_input_scale", 256, 96)) return 1;
    if (linear_init(&model->enc_gru3_recurrent, arrays, "enc_gru3_recurrent_bias", "enc_gru3_recurrent_subias", "enc_gru3_recurrent_weights_int8","enc_gru3_recurrent_weights_float", NULL, NULL, "enc_gru3_recurrent_scale", 32, 96)) return 1;
    if (linear_init(&model->enc_gru4_input, arrays, "enc_gru4_input_bias", "enc_gru4_input_subias", "enc_gru4_input_weights_int8","enc_gru4_input_weights_float", "enc_gru4_input_weights_idx", NULL, "enc_gru4_input_scale", 352, 96)) return 1;
